# Shared environment for the Emscripten + OpenCV wasm build.
#
# Dot-source from the other build scripts:
#     . "$PSScriptRoot\_env.ps1"
#
# The emsdk checkout is expected to live outside the repository (or at $env:EMSDK_DIR).
# Required layout (what `emsdk install latest` produces):
#     <emsdk>/upstream/emscripten/emcc.exe
#     <emsdk>/upstream/bin/clang.exe
#     <emsdk>/node/<ver>/node.exe
#     <emsdk>/python/<ver>/python.exe
#     <emsdk>/.emscripten             (EM_CONFIG, generated by this script if missing)

$ErrorActionPreference = 'Stop'

$script:RepoRoot = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path

if (-not $env:EMSDK_DIR) {
    if ($env:EMSDK) {
        # `emsdk activate` exports EMSDK; reuse it when present.
        $env:EMSDK_DIR = $env:EMSDK
    } else {
        # Default: a sibling `emsdk` checkout next to this repository.
        $env:EMSDK_DIR = Join-Path (Split-Path $script:RepoRoot -Parent) 'emsdk'
    }
}
if (-not (Test-Path $env:EMSDK_DIR)) {
    throw "Emscripten SDK not found at '$env:EMSDK_DIR'. Install emsdk and/or set EMSDK_DIR (see docs/build.md)."
}
$script:EmsdkRoot = (Resolve-Path $env:EMSDK_DIR).Path

$emccExe = Join-Path $EmsdkRoot 'upstream\emscripten\emcc.exe'
if (-not (Test-Path $emccExe)) {
    throw "Emscripten SDK not found at '$EmsdkRoot'. Install it with emsdk (see README) or set EMSDK_DIR."
}

# Newest node/python shipped with emsdk.
function Get-EmsdkToolDir([string]$Name) {
    $base = Join-Path $EmsdkRoot $Name
    if (-not (Test-Path $base)) { return $null }
    $dirs = Get-ChildItem $base -Directory | Sort-Object Name -Descending
    if (-not $dirs) { return $null }
    return $dirs[0].FullName
}
$script:NodeDir = Get-EmsdkToolDir 'node'
$script:PythonDir = Get-EmsdkToolDir 'python'

# EM_CONFIG: emscripten reads it at startup. Regenerate if missing so the checkout is
# usable without running `emsdk activate` (which is flaky behind some proxies).
$script:EmConfig = Join-Path $EmsdkRoot '.emscripten'
if (-not (Test-Path $EmConfig)) {
    $cfg = @(
        "LLVM_ROOT = '`$CFGDIR/upstream/bin'"
        "BINARYEN_ROOT = '`$CFGDIR/upstream'"
    )
    if ($NodeDir) {
        $cfg += "NODE_JS = '`$CFGDIR/node/$((Split-Path $NodeDir -Leaf))/node.exe'"
    }
    Set-Content -Path $EmConfig -Value ($cfg -join "`n") -Encoding ascii
    Write-Host "wrote $EmConfig"
}

$env:EMSDK = $EmsdkRoot
$env:EM_CONFIG = $EmConfig
if ($PythonDir) { $env:EMSDK_PYTHON = Join-Path $PythonDir 'python.exe' }
$toolPaths = @(
    (Join-Path $EmsdkRoot 'upstream\emscripten')
    (Join-Path $EmsdkRoot 'upstream\bin')
    $NodeDir
    $PythonDir
) | Where-Object { $_ }
$env:PATH = ($toolPaths -join ';') + ';' + $env:PATH

# OpenCV 5.x source tree. Override with $env:OPENCV_SRC or -OpenCVSrc.
$script:OpenCvSrc = if ($env:OPENCV_SRC) { (Resolve-Path $env:OPENCV_SRC).Path } else { Join-Path $RepoRoot '.cache\opencv' }
$env:OPENCV_SRC = $OpenCvSrc

$script:BuildRoot = Join-Path $RepoRoot 'build'
$script:OpenCvBuild = Join-Path $BuildRoot 'opencv-wasm'
$script:DistDir = Join-Path $RepoRoot 'dist'

function Invoke-Exe([string]$FilePath, [string[]]$Arguments) {
    Write-Host "> $FilePath $($Arguments -join ' ')"
    & $FilePath @Arguments
    if ($LASTEXITCODE -ne 0) {
        throw "command failed with exit code ${LASTEXITCODE}: $FilePath"
    }
}

Write-Verbose "repo=$RepoRoot emsdk=$EmsdkRoot node=$NodeDir python=$PythonDir opencv=$OpenCvSrc"
